{
  "id": "vuln-logkitty-ef2f673e",
  "message": "Using execSync with concatenated strings can lead to command injection vulnerabilities. Use execFileSync with an array of arguments to avoid this risk.",
  "severity": "ERROR",
  "languages": ["typescript"],
  "metadata": {
    "category": "security",
    "cwe": "CWE-78",
    "owasp": "A01:2021-Broken Access Control"
  },
  "pattern": "execSync(`${$CMD} $ARGS`)",
  "pattern_not": [
    "execFileSync($CMD, $ARGS)"
  ]
}

